/**
 * Manages Google Cloud Code / Gemini thought signatures for tool calls.
 * Gemini models with thinking require thought signatures in historical functionCall parts.
 */

const signatureMap = new Map<string, { signature: string; timestamp: number }>();

/**
 * Valid base64-encoded protobuf thought signature used by Antigravity IDE and 9router
 * as fallback whenever a historical tool call lacks an captured signature.
 */
export const DEFAULT_THOUGHT_SIGNATURE =
  "";

export function rememberThoughtSignature(toolUseId: string, signature: string): void {
  if (!toolUseId || !signature) return;
  if (signatureMap.size > 5000) {
    const oldestKey = signatureMap.keys().next().value;
    if (oldestKey) signatureMap.delete(oldestKey);
  }
  signatureMap.set(toolUseId, { signature, timestamp: Date.now() });
}

export function getThoughtSignature(toolUseId?: string): string {
  if (!toolUseId) return DEFAULT_THOUGHT_SIGNATURE;
  const entry = signatureMap.get(toolUseId);
  return entry?.signature || DEFAULT_THOUGHT_SIGNATURE;
}
